type Result<T> =
  | { status: "ok"; data: T }
  | { status: "error"; error: ErrorKind }

function unwrap<T>(promise: Promise<Result<T>>): Promise<T> {
  return promise.then((r) => {
    if (r.status === "error") {
      const err = new Error(r.error.message)
      Object.defineProperty(err, "cause", {
        value: r.error,
        configurable: true,
      })
      ;(err as Error & { kind: string }).kind = r.error.kind
      throw err
    }
    return r.data
  })
}

function wrap<T, A extends unknown[]>(
  fn: (...args: A) => Promise<Result<T>>,
): (...args: A) => Promise<T> {
  return (...args: A) => unwrap(fn(...args))
}

export function formatApiError(error: unknown): string {
  if (!(error instanceof Error)) return String(error)

  const kind = (error as Error & { kind?: unknown }).kind
  return typeof kind === "string" ? `${kind}: ${error.message}` : error.message
}

